window.DOCUTIS_PRAXIS_CATALOG = {
  chapters: {
    "1.1": {"germanName": "Acne vulgaris","turkishName": "Akne vulgaris (sivilce)","group": "Akneiform hastalıklar","guidePage": 20,"conditions": ["acne-vulgaris"],"verifiedCard": "acne-vulgaris"},
    "1.2": {"germanName": "Aktinische Keratose (inkl. Feldkanzerisierung)","turkishName": "Aktinik keratoz (alan kanserizasyonu dahil)","group": "Deri tümörleri ve öncülleri","guidePage": 25,"conditions": ["actinic-keratosis"],"verifiedCard": "actinic-keratosis"},
    "1.3": {"germanName": "Alopecia androgenetica","turkishName": "Androgenetik alopesi (erkek/kadın tipi saç dökülmesi)","group": "Saç ve pigment bozuklukları","guidePage": 29,"conditions": ["androgenetic-alopecia"],"appearance": "Erkekte bitemporal çekilme + vertex; kadında orta hat genişlemesi (Ludwig/“Christmas tree”), ön saç çizgisi korunur","diagnosis": "Öykü, dağılım ve trikoskopiyle foliküler minyatürleşmeyi değerlendir. Ani veya diffüz dökülme ve hiperandrojenizm bulgularında hedefli inceleme düşünülebilir.","alerts": "Ani diffüz dökülme, skar (yanık/kaşıntı, folikül kaybı), virilizasyon bulguları, çocukta","approach": "Tedavi seçimini dağılım, ilerleme ve hasta tercihine göre yap. Topikal ve sistemik seçeneklerde endikasyon, cinsiyet ve gebelik durumunu ayrı değerlendir.","sources": [["PubMed · 29178529","https://pubmed.ncbi.nlm.nih.gov/29178529/"]]},
    "1.4": {"germanName": "Alopecia areata","turkishName": "Alopesi areata (saçkıran)","group": "Saç ve pigment bozuklukları","guidePage": 33,"conditions": ["alopecia-areata"],"appearance": "Keskin sınırlı, inflamasyonsuz, skarsız alopesik yamalar; ünlem işareti kılları; tırnakta pitting","diagnosis": "Klinik görünüm ve trikoskopi. Tiroid veya diğer otoimmün durumlar için öykü ve muayeneye göre hedefli değerlendirme.","alerts": "Hızlı ilerleyen totalis/ universalis, çocukta yaygın, psikolojik yük, atipik/skarlı tablo","approach": "Sınırlı yama ile yaygın hastalığı ayır. Tedavi seçimini tutulum, aktivite, yaş ve psikososyal yüke göre yap.","sources": [["AWMF 013-104 · Register","https://register.awmf.org/de/leitlinien/detail/013-104"]]},
    "1.5": {"germanName": "Analekzem / Pruritus ani","turkishName": "Anal egzama / anal kaşıntı","group": "Ekzemler / proktolojik","guidePage": 36,"conditions": [],"appearance": "Perianal eritem, maserasyon, ragad, likenifikasyon; kaşıntı ve yanma","diagnosis": "Anamnez (ıslak mendil, sabun, hemoroid, inkontinans), proktoskopi, Epikutantest, tinea/ kandida/ streptokok sürüntüsü","alerts": "Kanama, kitle, dirençli tek taraflı plak (Paget, Bowen, karsinom), çocukta streptokok dermatiti, oksiyür","approach": "İrritanları ve nemi azalt, bariyeri koru. Enfeksiyon veya anorektal neden varsa ona yönelik yaklaşım planla.","sources": [["AWMF 013-007 · Register","https://register.awmf.org/de/leitlinien/detail/013-007"]]},
    "1.6": {"germanName": "Atopische Dermatitis (Neurodermitis)","turkishName": "Atopik dermatit (egzama)","group": "Ekzemalar ve bariyer bozuklukları","guidePage": 39,"conditions": ["atopic-dermatitis"],"appearance": "Kaşıntılı, kuru deri; yaşa göre yüz/ekstansör (bebek), fleksural (çocuk/erişkin), baş-boyun; likenifikasyon","diagnosis": "Klinik (öykü, atopi, dağılım); şiddet (SCORAD/EASI), süperenfeksiyon/eczema herpeticatum ayırımı","alerts": "Eczema herpeticatum (punch-out erozyonlar, ateş), eritrodermi, yaygın impetiginizasyon, gelişme geriliği","approach": "Temel bariyer bakımını sürdür. Atak tedavisini bölge, şiddet ve yaşa göre seç. Persistan orta-ağır hastalıkta tedaviyi yeniden değerlendir.","sources": [["AWMF 013-027 · Register","https://register.awmf.org/de/leitlinien/detail/013-027"]]},
    "1.7": {"germanName": "Chronisches Handekzem","turkishName": "Kronik el egzaması","group": "Ekzemalar ve bariyer bozuklukları","guidePage": 44,"conditions": [],"appearance": "El ayası/parmak yan yüzlerinde eritem, deskuamasyon, fissür, vezikül (dishidrotik), hiperkeratoz","diagnosis": "Mesleki/kişisel maruziyet anamnezi; >3 ay veya dirençte epikutan test; tinea/psoriasis ayırımı (KOH)","alerts": "Mesleki neden şüphesi (Hautarztverfahren), süperenfeksiyon, iş göremezlik riski","approach": "Islak iş ve tekrarlayan maruziyeti sorgula. Cilt koruma planıyla birlikte uygun antiinflamatuvar tedaviyi değerlendir.","sources": [["AWMF 013-053 · Register","https://register.awmf.org/de/leitlinien/detail/013-053"]]},
    "1.8": {"germanName": "Condylomata acuminata (Genitalwarzen)","turkishName": "Kondiloma akuminata (genital siğil)","group": "Viral deri enfeksiyonları","guidePage": 48,"conditions": [],"appearance": "Anogenital bölgede ten rengi–kahverengi, papillomatöz, sapsız veya saplı papüller","diagnosis": "Klinik; atipik, pigmentli, dirençli veya immünsüprese olguda biyopsi (IEN/ VIN/ PIN/ AIN); diğer STI’lar","alerts": "Çocukta anogenital siğil (cinsel istismar değerlendirmesi – özenle), immünsüpresyon, intraanal/ dev (Buschke-Löwenstein), pigmentli/ dirençli lezyon","approach": "Tedavi seçimini lezyon yeri, sayısı, gebelik ve immün duruma göre yap. Atipik lezyonlarda doku tanısı seçeneğini değerlendir.","sources": [["AWMF 082-008 · Register","https://register.awmf.org/de/leitlinien/detail/082-008"]]},
    "1.9": {"germanName": "Dermatofibrom (Histiozytom)","turkishName": "Dermatofibrom","group": "Benign deri tümörleri","guidePage": 52,"conditions": ["dermatofibroma"],"appearance": "Çoğunlukla bacakta, sert, kahverengimsi, 0,5–1 cm papül/ nodül; yandan sıkınca çukurlaşma (dimple sign)","diagnosis": "Klinik + dermoskopi (merkezi beyaz skar benzeri alan + periferik ince pigment ağı)","alerts": "Hızlı büyüme, >2 cm, ülserasyon, atipik dermoskopi (DFSP, melanom, BCC ayırt)","approach": "Tipik ve stabil lezyonda izlem düşünülebilir. Tanı belirsizse klinik ve dermoskopik bulgulara göre histoloji ihtiyacını değerlendir.","sources": []},
    "1.10": {"germanName": "Dyshidrotisches Ekzem (Dyshidrose, vesikuläres Hand-/Fußekzem)","turkishName": "Dizhidrotik egzama (el-ayak veziküler egzaması)","group": "Ekzemler","guidePage": 55,"conditions": [],"appearance": "Avuç içi, parmak yanları ve tabanda kaşıntılı, derin yerleşimli “sago taneleri” gibi veziküller; sonra deskuamasyon","diagnosis": "Klinik; KOH/ mantar kültürü (tinea pedis ‘id’ reaksiyonu ayırt), Epikutantest (kronik/ tekrarlayan), atopi sorgusu","alerts": "Artan ağrı, akıntı, bal rengi kabuk veya hızla yayılan erozyonlarda enfeksiyon olasılığını değerlendir.","approach": "El ve ayakta temas, irritasyon ve mantar olasılığını değerlendir. Bariyer bakımı ve bölgeye uygun topikal tedaviyi planla.","sources": [["AWMF 013-053 · Register","https://register.awmf.org/de/leitlinien/detail/013-053"]]},
    "1.11": {"germanName": "Epidermalzyste (Epidermoidzyste, „Atherom“)","turkishName": "Epidermal kist (epidermoid kist, “aterom”)","group": "Benign deri tümörleri / kistler","guidePage": 58,"conditions": [],"appearance": "Merkezde punktum (siyah nokta) olan, yer değiştirebilen, deri ile ilişkili yuvarlak nodül; kötü kokulu keratin içeriği","diagnosis": "Klinik; gerekirse sonografi; trichilemmal kist (kafa derisi) ayırımı","alerts": "Hızlı büyüme, sertleşme, ülserasyon, tekrarlayan nüks (malign dönüşüm nadir), çok sayıda kist + polipozis (Gardner)","approach": "Elektif eksizyon kararını nüks, semptom ve tanı güvenine göre ver. Akut inflamasyonla apseyi ayır.","sources": []},
    "1.12": {"germanName": "Erythrasma","turkishName": "Eritrazma","group": "Bakteriyel enfeksiyonlar","guidePage": 61,"conditions": ["erythrasma"],"appearance": "Kasık, aksilla, ayak parmak araları ve inframammär bölgede keskin sınırlı, kırmızı-kahverengi, ince skuamlı yama","diagnosis": "Wood ışığında mercan kırmızısı floresans (porfirin); KOH negatif (tinea/ kandida ayırımı)","alerts": "Diyabet (yaygın/ tekrarlayan formda tarayın), selülit","approach": "Kıvrımı kuru tut. Klinik ve mikrobiyolojik değerlendirmeyle gerekirse hedefe yönelik topikal tedavi seç.","sources": []},
    "1.13": {"germanName": "Fibroma molle (Akrochordon, weiches Fibrom)","turkishName": "Akrokordon (deri etiketi, yumuşak fibrom)","group": "Benign deri tümörleri","guidePage": 64,"conditions": [],"appearance": "Boyun, aksilla, kasık, göz kapağında yumuşak, saplı, ten rengi–kahverengi küçük papüller","diagnosis": "Morfoloji, sap ve yerleşimi değerlendir. Atipik oluşumda dermoskopi veya histoloji ihtiyacını gözden geçir.","alerts": "Pigmente/ atipik sapsız lezyon (nevüs, BCC, SK ayırt), tromboze akrokordon (koyu renk, ağrı)","approach": "Tipik akrokordonlarda semptom veya hasta tercihi girişim kararını yönlendirir. Atipik pigmente oluşumda önce tanıyı netleştir.","sources": []},
    "1.14": {"germanName": "Follikulitis, Furunkel und Karbunkel","turkishName": "Folikülit, fronkül ve karbonkül","group": "Bakteriyel deri enfeksiyonları","guidePage": 67,"conditions": ["bacterial-folliculitis"],"appearance": "Folikül merkezli püstül; fronkül: ağrılı, fluktuan kırmızı nodül; karbonkül: birleşmiş çok sayıda fronkül","diagnosis": "Klinik; tekrarlayanda sürüntü + antibiyogram, PVL-S. aureus/MRSA sorgula","alerts": "Yüz ortası fronkülü (sinüs ven trombozu riski), ateş, selülit, immünsüpresyon/DM","approach": "Yüzeyel folikülit, apse ve yayılan enfeksiyonu ayır. Drenaj ve antimikrobiyal gereksinimi yaygınlık ve riskle birlikte değerlendir.","sources": [["AWMF 082-006 · Register","https://register.awmf.org/de/leitlinien/detail/082-006"],["PubMed · 30920745","https://pubmed.ncbi.nlm.nih.gov/30920745/"]]},
    "1.15": {"germanName": "Hand-Fuß-Mund-Krankheit","turkishName": "El-ayak-ağız hastalığı","group": "Viral enfeksiyonlar","guidePage": 71,"conditions": [],"appearance": "Ağızda aftöz erozyonlar, el içi ve tabanlarda oval, gri-beyaz veziküller; gluteal papüller; Coxsackie A6’da yaygın/ atipik ve erişkinde de görülür","diagnosis": "Klinik; atipikte PCR (vezikül/ dışkı/ boğaz)","alerts": "Dehidratasyon (yeme–içme reddi), nörolojik bulgular (EV-A71: ensefalit, akut flasid paralizi), yüksek ateş >3 gün","approach": "Sıvı alımı ve ağız ağrısına odaklan. Çocuk içemiyorsa veya nörolojik bulgu varsa erken değerlendirme gerekir.","sources": []},
    "1.16": {"germanName": "Herpes simplex (labialis/genitalis)","turkishName": "Herpes simpleks (uçuk / genital herpes)","group": "Viral deri enfeksiyonları","guidePage": 74,"conditions": ["herpes-simplex"],"appearance": "Eritemli zemin üzerinde gruplanmış veziküller, erozyon ve kabuk; prodromal yanma/ karıncalanma","diagnosis": "Klinik; atipik/genital/ immünsüpresyonda HSV-PCR sürüntü","alerts": "Eczema herpeticatum, göz tutulumu (keratit), yenidoğan, immünsüpresyon, gebelik sonunda genital herpes","approach": "Yerleşim, ilk atak veya nüks, gebelik ve immün durum tedavi kararını değiştirir. Göz tutulumu ayrı değerlendirilir.","sources": [["AWMF 059-006 · Register","https://register.awmf.org/de/leitlinien/detail/059-006"]]},
    "1.17": {"germanName": "Herpes zoster (Gürtelrose)","turkishName": "Herpes zoster (zona)","group": "Viral deri enfeksiyonları","guidePage": 78,"conditions": ["herpes-zoster"],"appearance": "Tek dermatomda, orta hattı geçmeyen gruplanmış veziküller; öncesinde ağrı/ disestezi","diagnosis": "Klinik; atipik/ immünsüprese/ dissemine olguda VZV-PCR","alerts": "Z. ophthalmicus (Hutchinson işareti), Z. oticus (fasiyal parezi), dissemine, immünsüpresyon, motor defisit","approach": "Antiviral gereksinimini başlangıç zamanı, risk ve yerleşime göre değerlendir. Göz, kulak veya yaygın tutulumda gecikme olmasın.","sources": [["AWMF 013-023 · Register","https://register.awmf.org/de/leitlinien/detail/013-023"]]},
    "1.18": {"germanName": "Hyperhidrosis (primär fokal)","turkishName": "Hiperhidrozis (primer fokal aşırı terleme)","group": "Kronik inflamatuvar hastalıklar (özel)","guidePage": 82,"conditions": [],"appearance": "Bilateral simetrik aşırı terleme (aksilla, avuç, taban, yüz), uyurken olmaz; başlangıç genç yaş","diagnosis": "Klinik + HDSS; gerekirse Minor iyot-nişasta testi, gravimetri; sekonder nedenler (gece terlemesi, tek taraflı, ilaç, endokrin)","alerts": "Gece terlemesi, kilo kaybı, ateş, asimetrik/ tek taraflı (nörolojik), geç başlangıç → sekonder hiperhidroz araştırması","approach": "Primer fokal ve sekonder terlemeyi ayır. Lokal tedaviden girişime geçişi yerleşim ve işlev kaybına göre değerlendir.","sources": [["AWMF 013-059 · Register","https://register.awmf.org/de/leitlinien/detail/013-059"]]},
    "1.19": {"germanName": "Impetigo contagiosa","turkishName": "İmpetigo (bulaşıcı impetigo)","group": "Bakteriyel deri enfeksiyonları","guidePage": 85,"conditions": ["impetigo"],"appearance": "Bal sarısı kabuklu erozyonlar (yüz, burun-ağız çevresi); büllöz formda gevşek büller","diagnosis": "Klinik; tekrarlayan/ yaygın veya tedaviye yanıtsız olguda sürüntü + antibiyogram","alerts": "Ateş, selülit, yaygın büllöz tablo (SSSS ayırımı), yenidoğan, post-streptokokal GN belirtileri","approach": "Sınırlı ve yaygın hastalıkta yaklaşımı ayrı planla. Antibiyotik seçimini yerel direnç ve kılavuzla eşleştir.","sources": []},
    "1.20": {"germanName": "Insektenstichreaktion (lokal, verstärkt lokal, Prurigo simplex acuta)","turkishName": "Böcek ısırığı/ sokması reaksiyonu","group": "Alerjik / çevresel","guidePage": 88,"conditions": [],"appearance": "Kaşıntılı ürtikeryal papül/ seropapül, merkezde punktum; büyük lokal reaksiyon >10 cm, 24–48 sa’de pik","diagnosis": "Klinik; sistemik reaksiyonda (yaygın ürtiker, dispne, hipotansiyon) triptaz ve arı/ eşek arısı spesifik IgE (komponent) – Bienen-/ Wespengift-LL [47]","alerts": "Nefes darlığı, hipotansiyon, yaygın reaksiyon veya ağız ve boğaz içi sokma.","approach": "Lokal reaksiyonla sistemik reaksiyonu ayır. Solunum veya dolaşım bulgularında anafilaksi olasılığı önceliklidir.","sources": [["AWMF 061-020 · Register","https://register.awmf.org/de/leitlinien/detail/061-020"]]},
    "1.21": {"germanName": "Keloid und hypertrophe Narbe","turkishName": "Keloid ve hipertrofik skar","group": "Skar / bağ dokusu","guidePage": 91,"conditions": [],"appearance": "Hipertrofik skar: yara sınırında, kabarık, zamanla geriler. Keloid: yara sınırını aşan, sert, parlak, kaşıntılı–ağrılı tümör (sternum, omuz, kulak memesi)","diagnosis": "Klinik (anamnez: travma, akne, piercing); ayırıcı tanı: DFSP, sarkoidoz skar","alerts": "Hızlı büyüme, ülserasyon, tipik olmayan lokalizasyon → biyopsi","approach": "Skarın yara sınırlarını aşıp aşmadığını ve semptomları değerlendir. Silikon ve girişimsel seçeneklerle nüks riskini konuş.","sources": [["AWMF 013-030 · Register","https://register.awmf.org/de/leitlinien/detail/013-030"]]},
    "1.22": {"germanName": "Keratosis pilaris","turkishName": "Keratozis pilaris","group": "Keratinizasyon bozuklukları","guidePage": 94,"conditions": [],"appearance": "Üst kol dış yüzü, uyluk, yanaklarda folliküler keratotik papüller, “tavuk derisi”; perifolliküler eritem","diagnosis": "Klinik; atopi/ iktiyoz vulgaris ile birlikte","alerts": "","approach": "Cilt bakımı ve toleransı öncele. Keratolitik ürün düşünülüyorsa yaşa ve uygulama alanına uygunluğunu kontrol et.","sources": []},
    "1.23": {"germanName": "Kontaktekzem (allergisch / irritativ)","turkishName": "Kontakt dermatit (alerjik / irritan)","group": "Ekzemalar ve bariyer bozuklukları","guidePage": 97,"conditions": ["contact-dermatitis"],"appearance": "Temas alanıyla sınırlı eritem, vezikül, kaşıntı (ACD sınırı aşabilir); kronikte likenifikasyon","diagnosis": "Maruziyet öyküsü ve dağılım. Alerjik kontakt dermatit şüphesinde uygun epikutan test ve okuma protokolünü değerlendir.","alerts": "Yüzde yaygın ödem, generalize (hematojen) kontakt ekzem, mesleki neden","approach": "Şüpheli temas etkenini belirle, maruziyeti azalt ve bariyeri destekle. Mesleki neden varsa işyeri korunmasını değerlendir.","sources": [["AWMF 013-055 · Register","https://register.awmf.org/de/leitlinien/detail/013-055"]]},
    "1.24": {"germanName": "Kutane Candidose / Candida-Intertrigo","turkishName": "Deri kandidiyazisi / kandidal intertrigo","group": "Mantar enfeksiyonları","guidePage": 101,"conditions": ["cutaneous-candidiasis"],"appearance": "Kıvrımlarda parlak kırmızı, maserasyonlu plak, kenarda satellit papül-püstüller","diagnosis": "Klinik + KOH (psödohif), gerekirse kültür; DM, obezite, antibiyotik, immünsüpresyon sorgula","alerts": "Bebekte yaygın, mukokutan kronik candidiasis, immünsüpresyon, sistemik semptom","approach": "Nem ve sürtünmeyi azalt. Mantar tedavisi kararını klinik, mikoloji ve tutulum yaygınlığına göre ver.","sources": []},
    "1.25": {"germanName": "Lentigo solaris (Altersfleck)","turkishName": "Solar lentigo (yaşlılık/ güneş lekesi)","group": "Pigmentasyon bozuklukları","guidePage": 104,"conditions": ["solar-lentigo"],"appearance": "Yüz, el sırtı, dekolteda düzgün renkli, açık–koyu kahverengi, keskin sınırlı makül","diagnosis": "Klinik + dermoskopi (“parmak izi” paterni, yenik kenar); yüzde Lentigo maligna ayırt edilmeli","alerts": "Asimetrik, çok renkli, büyüyen yüz lezyonu; dermoskopide asimetrik pigmente folikül ağızları, rhomboid yapılar (Lentigo maligna)","approach": "Kozmetik işlemden önce lezyonun benign görünümünü doğrula. Yüzde asimetrik veya değişen pigmentte lentigo maligna olasılığını değerlendir.","sources": []},
    "1.26": {"germanName": "Lichen simplex chronicus (Neurodermitis circumscripta)","turkishName": "Liken simpleks kronikus","group": "Ekzemler / pruritus","guidePage": 107,"conditions": [],"appearance": "Ense, ayak bileği, el sırtı, skrotum/ vulvada tek, likenifiye, kalınlaşmış, kaşıntılı plak","diagnosis": "Klinik; altta yatan neden (atopi, kontakt alerji, tinea, psikojenik, nöropatik kaşıntı) araştırılır","alerts": "Genital LSC’de LS ve vulvar intraepitelyal neoplazi ayırt edilmeli; dirençte biyopsi","approach": "Kaşıma döngüsüyle birlikte kaşıntıyı başlatan nedeni ele al. Tek taraflı, genital veya dirençli plakta tanıyı yeniden değerlendir.","sources": []},
    "1.27": {"germanName": "Melanozytäre Naevi (Muttermale) – Dermatoskopie-Basics und Hautkrebs-Screening","turkishName": "Melanositik nevüsler (benler) – dermoskopi temel bilgileri ve deri kanseri taraması","group": "Benign deri tümörleri / tarama","guidePage": 110,"conditions": [],"appearance": "Simetrik ve düzenli paternler benign nevüslerde görülebilir. Morfoloji yaş, nevüs tipi ve anatomik bölgeye göre değişebilir.","diagnosis": "Tüm vücut muayenesi + dermoskopi (retiküler, globüler, homojen paternler); dijital takip (riskli hastada)","alerts": "ABCDE, yeni/ değişen ben (erişkin), kanama, “ugly duckling”, tek renkli olmayan subungual çizgi, çok sayıda atipik nevüs + aile öyküsü","approach": "Dermoskopi ve öyküyle risk değerlendir. Şüpheli lezyonun doku tanısı gereksinimini rutin taramadan ayrı ele al.","sources": []},
    "1.28": {"germanName": "Melasma","turkishName": "Melazma","group": "Saç ve pigment bozuklukları","guidePage": 113,"conditions": [],"appearance": "Yüzde (alın, yanak, üst dudak) simetrik, düzensiz sınırlı kahverengi maküller; gebelik/ oral kontraseptif ile ilişkili","diagnosis": "Klinik + Wood/ dermatoskopi; ilaç (fototoksik) ve kozmetik anamnezi","alerts": "Tek taraflı, düzensiz, hızla değişen pigment (lentigo maligna ayırımı), ilaç ilişkisi","approach": "Fotoproteksiyon ve tetikleyicilerle başla. Topikal ajan, majistral hazırlama veya sistemik seçenek düşünülürse gebelik ve ruhsatı ayrı kontrol et.","sources": []},
    "1.29": {"germanName": "Milien","turkishName": "Milia (milium kistleri)","group": "Benign deri tümörleri / kistler","guidePage": 117,"conditions": [],"appearance": "Göz çevresi ve yanaklarda 1–2 mm beyaz, sert, kubbe şeklinde papüller","diagnosis": "Klinik; sekonder milia: büllöz hastalık (EB, PCT, BP), skar, TCS kullanımı sonrası","alerts": "El sırtında bül + milia + hipertrikoz → porfiria cutanea tarda","approach": "Tipik milia çoğu zaman klinik olarak tanınır. İşlem kararı yaş, yerleşim ve hastanın talebine bağlıdır.","sources": []},
    "1.30": {"germanName": "Mollusca contagiosa (Dellwarzen)","turkishName": "Molluskum kontagiozum","group": "Viral deri enfeksiyonları","guidePage": 120,"conditions": ["molluscum-contagiosum"],"appearance": "2–5 mm, ortası göbekli, inci gibi papüller; çocukta gövde/kıvrım; erişkinde genital","diagnosis": "Klinik + dermatoskopi; erişkinde genital lezyonda STI ve yaygında HIV düşün","alerts": "İmmünsüpresyon/ HIV, göz kapağında konjonktivit, yaygın dev lezyon","approach": "İzlem veya girişimi şikâyet, atopi, yaygınlık, yaş ve bağışıklık durumuna göre değerlendir.","sources": [["PubMed · 28513067","https://pubmed.ncbi.nlm.nih.gov/28513067/"]]},
    "1.31": {"germanName": "Nagelpsoriasis","turkishName": "Tırnak psoriazisi","group": "Psoriasis","guidePage": 123,"conditions": ["nail-psoriasis"],"appearance": "Pitting (çukurlaşma), yağ lekesi (oil spot), onikoliz, subungual hiperkeratoz, tırnak distrofisi","diagnosis": "Klinik + mantar dışlama (KOH/ kültür/ PCR); PsA sorgusu (eklem ağrısı, sabah tutukluğu, daktilit); NAPSI","alerts": "PsA bulguları (romatoloji), tek tırnakta distrofi + kitle (tümör)","approach": "Matriks ve yatak tutulumunu ayır, eklem semptomlarını sorgula. Lokal ve sistemik tedavi seçeneklerini toplam hastalık yüküyle değerlendir.","sources": []},
    "1.32": {"germanName": "Nummuläres Ekzem (mikrobielles Ekzem)","turkishName": "Numuler (madeni para şeklinde) egzama","group": "Ekzemler","guidePage": 126,"conditions": [],"appearance": "Bacaklar, kol dış yüzleri ve gövdede keskin sınırlı, madeni para büyüklüğünde, eksüdatif–kabuklu, çok kaşıntılı plaklar","diagnosis": "Klinik; ayırıcı tanıda tinea (KOH), psoriasis, Bowen; dirençte Epikutantest","alerts": "İmpetiginizasyon, tedaviye rağmen tek plak → Bowen/ tinea düşünün","approach": "Bariyer bakımı ve topikal inflamasyon kontrolünü değerlendir. Tedaviye rağmen kalan tek plakta tinea veya Bowen olasılığını gözden geçir.","sources": []},
    "1.33": {"germanName": "Onychomykose (Tinea unguium)","turkishName": "Onikomikoz (tırnak mantarı)","group": "Mantar enfeksiyonları","guidePage": 129,"conditions": ["onychomycosis"],"verifiedCard": "onychomycosis"},
    "1.34": {"germanName": "Paronychie und Unguis incarnatus (eingewachsener Nagel)","turkishName": "Paronişi ve tırnak batması (unguis incarnatus)","group": "Tırnak hastalıkları / enfeksiyon","guidePage": 133,"conditions": ["chronic-paronychia"],"appearance": "Akut: tırnak kenarında ağrılı kızarıklık, şişlik, pü. Kronik: kütikül kaybı, kalınlaşmış tırnak kıvrımı. Batma: başparmak lateral kıvrımda granülasyon dokusu","diagnosis": "Klinik; kronik paronişide kandida/ irritan kontakt; tekrarlayan tek parmak lezyonunda tümör ayırımı (SCC, amelanotik melanom)","alerts": "Felon/ derin el enfeksiyonu, lenfanjit, diyabetik ayak, kemik tutulumu; tekrarlayan tek tırnak lezyonu (malignite)","approach": "Akut apse, kronik irritan paronişi ve mekanik tırnak batmasını ayrı değerlendir. Tek tırnakta dirençli olguda tanıyı tekrar sorgula.","sources": [["AWMF 013-106 · Register","https://register.awmf.org/de/leitlinien/detail/013-106"]]},
    "1.35": {"germanName": "Periorale Dermatitis","turkishName": "Perioral dermatit","group": "Hassas yüz dermatozları","guidePage": 136,"conditions": [],"appearance": "Ağız, nazolabial ve bazen periorbital monomorf küçük papül/papülopüstül, vermilyon kenarında dar boş şerit","diagnosis": "Klinik; tüm topikal steroid ve kozmetik kullanımı sorgulanır","alerts": "Çocukta granülomatöz form, ağır steroid bağımlılığı, sistemik bulgu (sarkoidoz DD)","approach": "Yüz ürünlerini ve topikal steroid kullanımını gözden geçir. Hastalık şiddetine göre lokal veya sistemik tedavi gereksinimini değerlendir.","sources": []},
    "1.36": {"germanName": "Pityriasis alba","turkishName": "Pitiriyazis alba","group": "Ekzemler / pigmentasyon","guidePage": 140,"conditions": [],"appearance": "Çocuklarda yüz ve kollarda sınırları silik, ince skuamlı, hipopigmente yamalar; yazın daha belirgin","diagnosis": "Klinik; Wood ışığında belirgin akromi yok (vitiligodan farkı), KOH (PV dışlama)","alerts": "Belirgin depigmentasyon (vitiligo), duyusal kayıp (lepra; endemik bölge öyküsü), mikozis fungoides (hipopigmente)","approach": "Nazik bariyer bakımı ve güneşten korunmayı konuş. Keskin depigmentasyon veya kalıcı atipik yamada tanıyı tekrar değerlendir.","sources": []},
    "1.37": {"germanName": "Pityriasis versicolor","turkishName": "Pityriasis versikolor (tinea versikolor)","group": "Mantar enfeksiyonları","guidePage": 143,"conditions": ["pityriasis-versicolor"],"appearance": "Gövde üst kısmında hipo- veya hiperpigmente, ince skuamlı, birleşen maküller; kazımada skuam (“Hobelspan”)","diagnosis": "Klinik + KOH (“spagetti ve köfte”), Wood ışığı (sarı-yeşil)","alerts": "Nadir; immünsüpresyon, çok yaygın/ dirençli","approach": "Topikal antifungal seçimini yaygınlığa ve önceki yanıta göre yap. Tedaviden sonra pigment farkı bir süre kalabilir.","sources": [["PubMed · 29376896","https://pubmed.ncbi.nlm.nih.gov/29376896/"]]},
    "1.38": {"germanName": "Postinflammatorische Hyperpigmentierung","turkishName": "Postinflamatuvar hiperpigmentasyon (PIH)","group": "Saç ve pigment bozuklukları","guidePage": 146,"conditions": [],"appearance": "Önceki inflamasyon yerinde kahverengi–gri maküller; koyu ten tiplerinde belirgin","diagnosis": "Klinik; öykü (akne, ekzema, yanık, lazer/ peeling); dermal PIH (gri-mavi) daha inatçı","alerts": "Pigment dağılımı inflamasyonla uyumsuz, ilaç ilişkili pigmentasyon (Minocyclin, Amiodaron), melanom ayırımı","approach": "Önceki inflamasyonu kontrol et ve fotoproteksiyonu planla. Nedeni açıklanmayan veya değişen lezyonda tanıyı yeniden değerlendir.","sources": []},
    "1.39": {"germanName": "Psoriasis vulgaris","turkishName": "Psoriasis vulgaris (sedef hastalığı)","group": "Papüloskuamöz ve ürtikeryal hastalıklar","guidePage": 149,"conditions": ["plaque-psoriasis"],"appearance": "Keskin sınırlı, gümüş beyazı skuamlı eritematöz plaklar; dirsek, diz, saçlı deri, sakral; tırnak pitting/ yağ lekesi","diagnosis": "Klinik; şiddet PASI/ BSA/ DLQI; psoriatik artrit (eklem ağrısı, sabah tutukluğu) ve komorbidite taraması","alerts": "Eritrodermi, generalize püstüler psoriasis, PsA belirtileri, sistemik steroid sonrası alevlenme","approach": "Tedavi basamağını yaygınlık, özel bölgeler, eklem semptomları ve yaşam kalitesi belirler. Topikal, fototerapi ve sistemik seçenekleri ayrı değerlendir.","sources": [["AWMF 013-001 · Register","https://register.awmf.org/de/leitlinien/detail/013-001"]]},
    "1.40": {"germanName": "Rosazea","turkishName": "Rozasea (gül hastalığı)","group": "Akneiform / hassas yüz dermatozları","guidePage": 153,"conditions": ["rosacea"],"verifiedCard": "rosacea"},
    "1.41": {"germanName": "Seborrhoische Dermatitis","turkishName": "Seboreik dermatit","group": "Ekzemalar ve bariyer bozuklukları","guidePage": 157,"conditions": ["seborrheic-dermatitis"],"appearance": "Saçlı deri, kaş, nazolabial, kulak arkası, presternal bölgede yağlı sarı skuam + eritem","diagnosis": "Klinik; psoriasis, rozasea, tinea, LE ayırımı; ani ağır başlangıçta HIV/Parkinson düşün","alerts": "Bebekte yaygın/eritrodermik tablo, immünsüpresyon (HIV), tedaviye dirençli → biyopsi","approach": "Saçlı deri ve yüz için ayrı uygulama planı kur. Nüks ve irritasyon, tedavi ve bakım seçimini etkiler.","sources": [["PubMed · 25933684","https://pubmed.ncbi.nlm.nih.gov/25933684/"]]},
    "1.42": {"germanName": "Seborrhoische Keratose (Alterswarze)","turkishName": "Seboreik keratoz","group": "Deri tümörleri ve öncülleri","guidePage": 161,"conditions": ["seborrheic-keratosis"],"appearance": "“Yapıştırılmış gibi” duran, kahverengi–siyah, verrüköz, yağlı görünümlü plak; gövde, yüz","diagnosis": "Klinik + dermatoskopi (milia benzeri kistler, komedon benzeri açıklıklar, beyin kıvrımı paterni); şüphede biyopsi","alerts": "Yeni büyüme, kanama, ülserasyon veya dermoskopik atipide yeniden değerlendir.","approach": "Değişen veya atipik oluşumda dermoskopi ve gerekirse histolojiyi değerlendir. Tipik lezyonda girişim kararı semptom ve tercihe bağlıdır.","sources": []},
    "1.43": {"germanName": "Skabies (Krätze)","turkishName": "Skabiyez (uyuz)","group": "Parazitler","guidePage": 164,"conditions": ["scabies"],"appearance": "Gece artan kaşıntı; interdigital, el bileği, aksilla, areola, genital, gluteal papüller ve tüneller; bebekte avuç-taban/baş","diagnosis": "Dermatoskopi (“delta kanadı/ jet uçağı”), mikroskopi (akar, yumurta, skibala)","alerts": "Scabies crustosa, kurum salgını, immünsüpresyon, yaygın impetiginizasyon","approach": "Hastayı ve yakın temaslıları aynı plan içinde değerlendir. Yaş, gebelik, kurum salgını ve kabuklu uyuz tedavi seçimini değiştirir.","sources": [["AWMF 013-052 · Register","https://register.awmf.org/de/leitlinien/detail/013-052"]]},
    "1.44": {"germanName": "Sonnenbrand (Dermatitis solaris)","turkishName": "Güneş yanığı (dermatitis solaris)","group": "Fotodermatozlar / fiziksel","guidePage": 168,"conditions": [],"appearance": "UV maruziyetinden 4–24 saat sonra ağrılı, keskin sınırlı eritem, ödem; ağır formda bül, ateş, baş ağrısı","diagnosis": "Klinik; fototoksik ilaç/ bitki öyküsü (fototoksik reaksiyon ayırt edilmeli)","alerts": "Geniş alanda bül, ateş, dehidratasyon, bilinç bulanıklığı (güneş çarpması), bebek/ küçük çocuk","approach": "Yanık alanı, bül ve genel durumu değerlendir. Sıvı kaybı, yaygın bül veya sistemik belirti varsa erken muayene önemlidir.","sources": []},
    "1.45": {"germanName": "Stauungsdermatitis (Stauungsekzem)","turkishName": "Staz dermatiti (venöz egzama)","group": "Ekzemler / flebolojik","guidePage": 171,"conditions": [],"appearance": "Alt bacak iç yüzü (malleol) çevresinde kahverengi pigmentasyon, eritem, skuam, ödem; atrophie blanche, lipodermatoskleroz","diagnosis": "Klinik + Duplex sonografi (venöz reflü); ABI (kompresyon öncesi), Epikutantest (sık sensitizasyon)","alerts": "Bilateral “kırmızı bacak” erizipel değildir; tek taraflı akut ağrı/ şişlikte DVT dışlanmalı; ülser gelişimi","approach": "Venöz yetmezliği değerlendir ve kompresyon öncesi arteriyel dolaşımı kontrol et. Ekzema ve ödemi birlikte ele al.","sources": []},
    "1.46": {"germanName": "Talgdrüsenhyperplasie","turkishName": "Sebase hiperplazi","group": "Benign deri tümörleri","guidePage": 174,"conditions": [],"appearance": "Alın, yanaklarda 2–5 mm sarımsı, göbekli (merkezi çukur) papüller","diagnosis": "Klinik + dermoskopi (merkezde göbek etrafında taç şeklinde “crown” damarlar, sarı lobüller)","alerts": "BCC ayırımı (arborizan damarlar, parlak), hızlı büyüme; çok sayıda + sebase tümörlerde Muir-Torre sendromu","approach": "Tipik lezyonda semptom ve hasta tercihini değerlendir. Tek, değişen veya atipik lezyonda BCC ayrımını gözden geçir.","sources": []},
    "1.47": {"germanName": "Telogenes Effluvium","turkishName": "Telogen efluvyum","group": "Saç hastalıkları","guidePage": 177,"conditions": [],"appearance": "Tetikleyiciden 2–4 ay sonra başlayan, yaygın, saçlı derinin tümünde dökülme; pozitif “pull test”; skar yok","diagnosis": "Anamnez (ateş, doğum, ameliyat, diyet, ilaç, stres), pull test, trikoskopi; Lab: kan sayımı, ferritin, TSH (± çinko, D vitamini, gerekirse hormonlar)","alerts": "Skarlı alopesi bulguları (folikül ağzı kaybı), yamalı dökülme (AA), sistemik hastalık belirtileri, kadında hiperandrojenizm","approach": "Saç döngüsünü etkileyen tetikleyicileri ve ilaçları sorgula. Kalıcı, skarlı veya bölgesel dökülmede ayırıcı tanıyı genişlet.","sources": [["PubMed · 42823125","https://pubmed.ncbi.nlm.nih.gov/42823125/"]]},
    "1.48": {"germanName": "Tinea corporis, Tinea cruris und Tinea pedis","turkishName": "Tinea korporis, tinea kruris ve tinea pedis (deri mantarı)","group": "Mantar enfeksiyonları","guidePage": 180,"conditions": ["tinea-corporis","tinea-cruris","tinea-pedis"],"appearance": "Kenarı aktif, skuamlı, ortası soluk halka plak; kasıkta simetrik değil; ayakta interdigital maserasyon/ mokasen tip","diagnosis": "KOH + kültür (dirençli/yaygın olguda PCR, direnç testi); steroid kullanımı sorgula (tinea incognito)","alerts": "Yaygın, tedaviye dirençli (T. indotineae), Majocchi granülomu, DM ayağında maserasyon/ selülit","approach": "Vücut, kasık ve ayak tutulumunu ayrı değerlendir. Yaygın, atipik veya dirençli tabloda enfeksiyonu ve önceki tedaviyi yeniden incele.","sources": [["AWMF 013-002 · Register","https://register.awmf.org/de/leitlinien/detail/013-002"]]},
    "1.49": {"germanName": "Urtikaria (akut und chronisch spontan)","turkishName": "Ürtiker (akut ve kronik spontan)","group": "Papüloskuamöz ve ürtikeryal hastalıklar","guidePage": 183,"conditions": ["chronic-urticaria"],"appearance": "Geçici (<24 sa) kaşıntılı kabarıklar ± anjiyoödem (≤72 sa); iz bırakmaz","diagnosis": "Akut: rutin tetkik yok; KSU >6 hf: diferansiyel kan sayımı + CRP/ESR (± total IgE, anti-TPO); UAS7, UCT","alerts": "Nefes darlığı, dil veya boğaz ödemi, hipotansiyon ya da bayılma hissi.","approach": "Akut ve kronik ürtikeri ayır. Solunum veya dolaşım bulgusu eşlik ediyorsa anafilaksi yönünden acil değerlendirme gerekir.","sources": [["AWMF 013-028 · Register","https://register.awmf.org/de/leitlinien/detail/013-028"]]},
    "1.50": {"germanName": "Varizellen (Windpocken)","turkishName": "Suçiçeği (varisella)","group": "Viral enfeksiyonlar","guidePage": 187,"conditions": [],"appearance": "Ateş + farklı evrelerde (“yıldızlı gökyüzü”) makül, papül, vezikül, kabuk; saçlı deri ve mukoza tutulumu","diagnosis": "Klinik; atipikte PCR (vezikül sürüntüsü)","alerts": "Pnömoni (erişkin, sigara içen, gebe), ensefalit/ serebellit, bakteriyel süperenfeksiyon (GAS: nekrotizan fasiit), immünsüpresyon, gebelik, yenidoğan","approach": "Yaş, gebelik, bağışıklık ve hastalık şiddeti antiviral ile izolasyon kararını değiştirir. Enfeksiyon kontrolünde RKI bilgilerini kullan.","sources": [["RKI · Varizellen / Herpes zoster","https://www.rki.de/DE/Aktuelles/Publikationen/RKI-Ratgeber/Ratgeber/Ratgeber_Varizellen.html"]]},
    "1.51": {"germanName": "Verrucae vulgares und plantares (Warzen)","turkishName": "Siğiller (verruka vulgaris ve plantaris)","group": "Viral deri enfeksiyonları","guidePage": 190,"conditions": ["cutaneous-warts"],"appearance": "Pütürlü, keratotik papül; plantar: deri çizgilerini kesen, nokta kanamalı (trombozlu kapiller) lezyon","diagnosis": "Klinik + dermatoskopi; nasır (Clavus) ve atipik/ tek tırnak çevresinde SCC ayırımı","alerts": "İmmünsüpresyon (transplant), tek, büyüyen, ülserleşen veya periungual dirençli lezyon (SCC)","approach": "Spontan gerileme olasılığıyla semptom ve yerleşimi birlikte değerlendir. Tırnak çevresindeki dirençli veya atipik lezyonda tanıyı tekrar sorgula.","sources": []},
    "1.52": {"germanName": "Vitiligo","turkishName": "Vitiligo (ala hastalığı)","group": "Saç ve pigment bozuklukları","guidePage": 194,"conditions": ["vitiligo"],"appearance": "Keskin sınırlı, depigmente (süt beyazı) maküller; yüz, eller, perioral/ periorbital, genital; Köbner","diagnosis": "Klinik muayene ve gerekirse Wood ışığı. Aktiviteyi değerlendir ve öyküye göre eşlik eden otoimmün hastalık açısından incele.","alerts": "Hızla ilerleyen yaygın tablo, psikolojik yük, eşlik eden otoimmünite","approach": "Aktiviteyi, yaygınlığı ve hassas bölgeleri belirle. Bölgeye göre topikal tedavi ve fototerapi seçeneklerini değerlendir.","sources": [["AWMF 013-093 · Register","https://register.awmf.org/de/leitlinien/detail/013-093"]]},
    "1.53": {"germanName": "Xerosis cutis und Pruritus im Alter (Exsikkationsekzem)","turkishName": "Kuru cilt ve yaşlılıkta kaşıntı (asteatotik egzama)","group": "Ekzemalar ve bariyer bozuklukları","guidePage": 198,"conditions": [],"appearance": "Alt bacaklarda “craquelé” (kırık porselen) görünümü, ince skuam, ekskoriasyon; kışın artar","diagnosis": "Kronik kaşıntıda (>6 hf) sistemik nedenleri dışla: KC, böbrek, tiroid, demir, hematolojik, ilaç","alerts": "Yaygın kaşıntı + kilo kaybı/gece terlemesi/ ikter; ilk kez ortaya çıkan büllöz pemfigoid (prodrom)","approach": "Bariyer bakımını düzenle. Yaygın ve açıklanamayan kaşıntıda eşlik eden sistemik nedenleri araştır.","sources": [["AWMF 013-048 · Register","https://register.awmf.org/de/leitlinien/detail/013-048"]]},
    "2.1": {"germanName": "Anaphylaxie und Angioödem","turkishName": "Anafilaksi ve anjiyoödem","group": "Acil durumlar","guidePage": 203,"conditions": [],"appearance": "Ani solunum veya dolaşım bozukluğu, bazen deri veya mukoza ve gastrointestinal bulgularla birlikte. Deri bulgusu görülmeyebilir.","diagnosis": "Klinik değerlendirme ve acil yanıt önceliklidir. Sonraki alerji incelemesini olay öyküsüne göre planla.","alerts": "Stridor, ses kısıklığı, nefes darlığı, hipotansiyon, bilinç bozukluğu; ACE-I ile dil/ larinks ödemi","approach": "Solunum veya dolaşım etkilenmesiyle anafilaksi şüphesinde acil yardım ve yerel acil protokolü devreye girer.","sources": [["AWMF 061-025 · Anaphylaxie","https://register.awmf.org/de/leitlinien/detail/061-025"]]},
    "2.2": {"germanName": "Arzneimittelexanthem und SJS/TEN (epidermale Nekrolyse)","turkishName": "İlaç döküntüsü ve SJS/TEN (epidermal nekroliz)","group": "Acil durumlar","guidePage": 206,"conditions": [],"appearance": "Basit ekzantemde makül ve papüller görülebilir. Ağrılı eritem, atipik hedef lezyonlar, büller, epidermal ayrılma veya mukoza erozyonları ağır reaksiyon düşündürebilir.","diagnosis": "İlaç zaman çizelgesi, deri ve mukoza muayenesi, sistemik belirtiler. Şüpheli ağır reaksiyonu gecikmeden uzman merkezle değerlendir.","alerts": "Mukoza erozyonu, deri ağrısı, bül, Nikolsky +, ateş, eozinofili/ KC bozukluğu (DRESS), yüz ödemi","approach": "Deri ağrısı, bül, epidermal ayrılma veya mukoza bulgusu varsa ağır ilaç reaksiyonu açısından acil hastane değerlendirmesi gerekir.","sources": [["AWMF 013-103 · SJS/TEN","https://www.awmf.org/aktuelles/awmf-aktuell/diagnostik-und-therapie-der-epidermalen-nekrolyse-stevens-johnson-syndrom-und-toxisch-epidermale-nekrolyse-sjs-ten"],["AWMF 013-103 · Register","https://register.awmf.org/de/leitlinien/detail/013-103"]]},
    "2.3": {"germanName": "Basalzellkarzinom","turkishName": "Bazal hücreli karsinom (BCC)","group": "Deri tümörleri","guidePage": 209,"conditions": ["basal-cell-carcinoma"],"appearance": "İnci gibi parlak, telanjiektazili papül/ nodül, ortası ülsere (“rodent ulcer”); süperfisyel: gövdede eritemli ince plak","diagnosis": "Dermatoskopi (arborizan damarlar, mavi-gri ovoid yuvalar, yaprak benzeri alanlar); biyopsi ile alt tip","alerts": "Yüz orta hattı/ göz-burun-kulak çevresi, morfeaform/ infiltratif alt tip, nüks, büyük tümör, immünsüpresyon","approach": "Tedaviyi histolojik alt tip, yerleşim, sınır ve nüks riskine göre planla. Girişimsel ve topikal seçeneklerin kapsamı farklıdır.","sources": [["AWMF 032-021 · Register","https://register.awmf.org/de/leitlinien/detail/032-021"]]},
    "2.4": {"germanName": "Bullöses Pemphigoid","turkishName": "Büllöz pemfigoid","group": "Otoimmün ve inflamatuvar hastalıklar (özel)","guidePage": 212,"conditions": ["bullous-pemphigoid"],"appearance": "Yaşlıda kaşıntılı ürtikeryal plaklar üzerinde gergin, berrak/hemorajik büller; mukoza nadiren","diagnosis": "Biyopsi (histoloji + perilezyonel DIF: lineer IgG/C3), serolojide BP180/BP230 ELISA; ilaç (DPP-4 inhibitörü) anamnezi","alerts": "Yaygın büller, sekonder enfeksiyon, kötü genel durum, mukoza tutulumu (MMP ayırımı)","approach": "Yaygınlık, mukoza bulgusu, yaş ve eşlik eden hastalıklarla tedavi seçimini birlikte değerlendir. Doku doğrulaması ve takip planı önemlidir.","sources": [["AWMF 013-071 · Register","https://register.awmf.org/de/leitlinien/detail/013-071"]]},
    "2.5": {"germanName": "Dermatitis herpetiformis Duhring","turkishName": "Dermatitis herpetiformis (Duhring hastalığı)","group": "Otoimmün büllöz hastalıklar","guidePage": 216,"conditions": ["dermatitis-herpetiformis"],"appearance": "Dirsek, diz, sakrum, saçlı deride simetrik, çok kaşıntılı, gruplanmış papülovezikül ve ekskoriasyonlar","diagnosis": "Lezyon kenarı sağlam deriden direkt IF (papiller dermiste granüler IgA) + serum anti-tTG/ anti-eTG IgA (total IgA ile); histoloji","alerts": "Dapson’da hemoliz/ methemoglobinemi, agranülositoz, DRESS; enteropati semptomları, lenfoma riski (uzun süre diyetsiz)","approach": "Dermatolojik tanıyı çölyak değerlendirmesiyle ilişkilendir. Beslenme ve farmakolojik seçenekleri güvenlik izlemiyle birlikte planla.","sources": [["AWMF 021-021 · Register","https://register.awmf.org/de/leitlinien/detail/021-021"]]},
    "2.6": {"germanName": "Dermatomyositis (kutane Manifestationen)","turkishName": "Dermatomiyozit (deri bulguları)","group": "Kollajenozlar","guidePage": 219,"conditions": ["dermatomyositis"],"appearance": "Heliotrop eritem (göz kapakları), Gottron papülleri (eklem üstleri), şal/ V-belirtisi, kaşıntılı poikiloderma, periungual telanjiektazi, “mekanik eli”","diagnosis": "Biyopsi, CK/ aldolaz, miyozit antikorları (TIF1-γ, NXP2, MDA5, Mi-2, Jo-1), EMG/ MR; erişkinde malignite taraması","alerts": "Disfaji, dispne (ILD; özellikle anti-MDA5), kas güçsüzlüğü, malignite bulguları","approach": "Deri bulgularına ek olarak kas, akciğer ve yutma belirtilerini sorgula. Sistemik değerlendirmeyi ilgili uzmanlıklarla planla.","sources": [["AWMF 030-054 · Register","https://register.awmf.org/de/leitlinien/detail/030-054"]]},
    "2.7": {"germanName": "Eczema herpeticatum","turkishName": "Ekzema herpetikum (Kaposi variseliform erüpsiyonu)","group": "Acil durumlar","guidePage": 222,"conditions": [],"appearance": "Atopik deride monomorf, göbekli veziküller ve “punch-out” erozyonlar, hemorajik kabuk; ateş, halsizlik","diagnosis": "Klinik + HSV-PCR (vezikül tabanı); bakteriyel süperenfeksiyon için sürüntü","alerts": "Göz çevresi, ateş, yaygın tutulum, bebek, immünsüpresyon","approach": "Özellikle göz çevresi, yaygın tutulum veya sistemik bulguda hızlı değerlendirme gerekir. HSV örneğinin alınması gerekli tedaviyi geciktirmemeli.","sources": [["NICE CG57 · Eczema herpeticum","https://www.nice.org.uk/guidance/cg57/chapter/Recommendations"]]},
    "2.8": {"germanName": "Erysipel und Phlegmone","turkishName": "Erizipel ve selülit (flegmon)","group": "Acil durumlar","guidePage": 225,"conditions": ["erysipelas"],"appearance": "Keskin sınırlı, sıcak, ağrılı eritem (erizipel), daha derin ve sınırı belirsiz (selülit); ateş, lenfanjit","diagnosis": "Klinik; ayırıcı: DVT, staz dermatiti (bilateral!), kontakt dermatit, nekrotizan fasiit (ağrı orantısız)","alerts": "Ateş/titreme, sepsis bulguları, hızlı yayılım, bül/nekroz, orantısız ağrı (nekrotizan fasiit), yüz tutulumu, DM/immünsüpresyon","approach": "Erizipel ve daha derin enfeksiyonu ayır. Hızlı yayılım, orantısız ağrı ve sistemik toksisite acil değerlendirme gerektirir.","sources": [["AWMF 082-006 · Register","https://register.awmf.org/de/leitlinien/detail/082-006"],["PubMed · 30920745","https://pubmed.ncbi.nlm.nih.gov/30920745/"]]},
    "2.9": {"germanName": "Erythema migrans (kutane Lyme-Borreliose)","turkishName": "Eritema migrans (Lyme hastalığı – deri)","group": "Enfeksiyonlar (özel)","guidePage": 228,"conditions": [],"appearance": "Kene ısırığından 3–30 gün sonra ≥5 cm, yavaş genişleyen, ortası solabilen eritem","diagnosis": "Klinik tanı – seroloji gerekmez (erken EM’de sıklıkla negatif)","alerts": "Çoklu EM, nörolojik semptom (fasiyal parezi, radikülit), kardiyak (AV blok), artrit, ACA","approach": "Tipik eritema migransı erken evre serolojisinden bağımsız değerlendir. Nörolojik, kardiyak veya eklem bulguları yaklaşımı değiştirir.","sources": [["AWMF 013-044 · Register","https://register.awmf.org/de/leitlinien/detail/013-044"]]},
    "2.10": {"germanName": "Erythema nodosum","turkishName": "Eritema nodozum","group": "Pannikülitler","guidePage": 231,"conditions": [],"appearance": "Pretibial bilateral, ağrılı, sıcak, kırmızı–mor subkutan nodüller; ateş, artralji; skar bırakmaz, “bruise-like” gerileme","diagnosis": "Klinik; neden araştırması: ASL/ boğaz sürüntüsü, CRP, akciğer grafisi (sarkoidoz/ TB), IGRA, gebelik/ OKS, IBD, Yersinia; atipikte derin biyopsi","alerts": "Ülserasyon veya asimetrik ve atipik dağılımda alternatif tanıyı araştır. Solunum veya sistemik belirtileri ayrıca değerlendir.","approach": "Nedeni araştırırken semptomatik bakımı planla. Ülserasyon ve atipik dağılım alternatif panikülit veya vaskülit düşündürür.","sources": []},
    "2.11": {"germanName": "Gonorrhö und Chlamydia-trachomatis-Infektion (inkl. Lymphogranuloma venereum)","turkishName": "Gonore ve Chlamydia trachomatis enfeksiyonu (LGV dahil)","group": "Cinsel yolla bulaşan enfeksiyonlar (Venerologie)","guidePage": 234,"conditions": [],"appearance": "Erkekte pürülan üretral akıntı, dizüri; kadında çoğu asemptomatik/ servisit; rektal/ faringeal enfeksiyon sıklıkla asemptomatik; dissemine gonokok: akral hemorajik püstül + artrit","diagnosis": "NAAT/ PCR (idrar, üretra, servikal/ vajinal, rektal, faringeal); gonorede tedavi öncesi kültür + antibiyogram (direnç!)","alerts": "Dissemine gonokok enfeksiyonu, PID (alt karın ağrısı, ateş), epididimit, gebelik, yenidoğan konjonktiviti, çocukta STI (istismar)","approach": "Gonore ve klamidyayı ayrı değerlendir. Anatomik örnekleme, direnç, gebelik ve partner yönetimi için güncel STI kılavuzuna bak.","sources": [["AWMF 059-004 · Register","https://register.awmf.org/de/leitlinien/detail/059-004"],["AWMF 059-005 · Register","https://register.awmf.org/de/leitlinien/detail/059-005"]]},
    "2.12": {"germanName": "Granuloma anulare","turkishName": "Granüloma anülare","group": "Granülomatöz hastalıklar","guidePage": 237,"conditions": [],"appearance": "El/ ayak sırtında ten rengi–eritemli papüllerin oluşturduğu halka şeklinde plaklar; merkez normal, skuam yok","diagnosis": "Klinik; gerekirse biyopsi (palizat granülom, müsin); tinea ayırımı (skuam yok, KOH negatif)","alerts": "Atipik (ülsere, skuamlı, yüz) → sarkoidoz, tinea, MF ayırımı; yaygın formda dislipidemi/ diyabet ilişkisi tartışmalı","approach": "Sınırlı ve asemptomatik tabloda izlem bir seçenektir. Yaygın veya atipikte histoloji ve tedavi hedefini yeniden değerlendir.","sources": [["PubMed · 40586485","https://pubmed.ncbi.nlm.nih.gov/40586485/"]]},
    "2.13": {"germanName": "Hidradenitis suppurativa / Acne inversa","turkishName": "Hidradenitis suppurativa (akne inversa)","group": "Kronik inflamatuvar hastalıklar (özel)","guidePage": 240,"conditions": [],"appearance": "Aksilla, inguinal, perianal, inframammär bölgelerde tekrarlayan ağrılı nodül, apse, sinüs trakt, köprü skar; çift komedon","diagnosis": "Klinik (tipik lezyon + lokalizasyon + kronisite); şiddet Hurley, IHS4; sonografi (sinüs trakt)","alerts": "Apse + ateş, sinüs traktlarda SCC (uzun süreli perianal/ gluteal), ağır ağrı, depresyon","approach": "Ağrı, tekrarlama ve tünelleri değerlendir. Medikal ve cerrahi seçeneklerin kapsamını evre ile birlikte planla.","sources": [["AWMF 013-012 · Register","https://register.awmf.org/de/leitlinien/detail/013-012"]]},
    "2.14": {"germanName": "Kaposi-Sarkom","turkishName": "Kaposi sarkomu","group": "Deri tümörleri (vasküler)","guidePage": 244,"conditions": ["kaposi-sarcoma"],"appearance": "Mor-kahverengi makül, plak ve nodüller; klasik formda yaşlı erkeklerde ayak/ bacakta; HIV’de yüz, ağız mukozası, gövde; ödem","diagnosis": "Biyopsi (HHV-8 LANA-1 immünohistokimya); HIV testi; evreleme (ağız, GI, akciğer)","alerts": "Ağız/ GI kanama, solunum semptomları (pulmoner KS), hızlı ilerleme, IRIS (ART başlangıcında alevlenme)","approach": "Histolojik doğrulamadan sonra alt tipi ve sistemik tutulumu değerlendir. Tedaviyi ilgili merkezle koordine et.","sources": [["AWMF 032-025 · Register","https://register.awmf.org/de/leitlinien/detail/032-025"]]},
    "2.15": {"germanName": "Kutane leukozytoklastische Vaskulitis (Immunkomplexvaskulitis, inkl. IgA-Vaskulitis)","turkishName": "Kutanöz lökositoklastik vaskülit (IgA vasküliti dahil)","group": "Vaskülitler","guidePage": 247,"conditions": [],"appearance": "Bacaklarda simetrik palpabl purpura, hemorajik vezikül/ bül, nekrotik merkez; ödem","diagnosis": "Biyopsi (<48 sa lezyon; histoloji + direkt IF – IgA?), idrar (hematüri/ proteinüri), kreatinin, kan sayımı, CRP, ANCA, kriyoglobulin, hepatit B/C, kompleman","alerts": "Böbrek tutulumu (hematüri, proteinüri), karın ağrısı/ GI kanama (IgA vaskülit), nörolojik/ pulmoner tutulum, ülserasyon/ nekroz, ateş","approach": "Kutanöz sınırlı ve organ tutulumu olan tabloyu ayır. Böbrek, gastrointestinal veya pulmoner bulgu değerlendirme önceliğini değiştirir.","sources": [["AWMF 013-111 · Register","https://register.awmf.org/de/leitlinien/detail/013-111"]]},
    "2.16": {"germanName": "Kutane Mastozytose (Urticaria pigmentosa / makulopapulöse kutane Mastozytose)","turkishName": "Kutanöz mastositoz (ürtikerya pigmentoza)","group": "Mast hücre hastalıkları","guidePage": 250,"conditions": [],"appearance": "Kahverengi-kırmızı makül/ papüller; sürtmekle kabarma ve kızarma (Darier belirtisi); çocukta tek mastositom veya yaygın lezyonlar","diagnosis": "Lezyon morfolojisi ve öyküyle başla. Kutanöz doğrulama ve sistemik inceleme gereksinimini yaş ve sistemik bulgulara göre uzmanla değerlendir.","alerts": "Anafilaksi (özellikle böcek sokması, ilaçlar, anestezi), çocukta yaygın büllöz form, erişkinde hepatosplenomegali/ sitopeni","approach": "Çocuk ve erişkinde kapsam farklıdır. Sistemik bulguları, anafilaksi öyküsünü ve uzman sevki ihtiyacını değerlendir.","sources": [["AWMF 013-058 · Register","https://register.awmf.org/de/leitlinien/detail/013-058"]]},
    "2.17": {"germanName": "Kutaner Lupus erythematodes","turkishName": "Kutan lupus eritematozus","group": "Otoimmün ve inflamatuvar hastalıklar (özel)","guidePage": 253,"conditions": ["discoid-lupus-erythematosus"],"appearance": "DLE: skarlaşan, atrofik, hiper/hipopigmente plaklar (yüz, kulak, saçlı deri – skarlı alopesi); SCLE: anüler/ papüloskuamöz, güneş gören alanlar","diagnosis": "Biyopsi (+ DIF), ANA, anti-Ro/SSA, ENA, dsDNA, hemogram, idrar, kompleman; SLE kriterleri; ilaç ilişkili SCLE (Terbinafin, PPI, HCTZ)","alerts": "Sistemik belirtiler (artrit, serozit, böbrek, sitopeni), hızlı skarlaşma, gebelikte anti-Ro (neonatal lupus)","approach": "Kutanöz alt tip ve sistemik bulguları belgele. Fotoproteksiyon, lokal tedavi ve sistemik seçenekleri riskle birlikte değerlendir.","sources": [["AWMF 013-060 · Register","https://register.awmf.org/de/leitlinien/detail/013-060"]]},
    "2.18": {"germanName": "Kutanes Plattenepithelkarzinom und Morbus Bowen","turkishName": "Kutan skuamöz hücreli karsinom (cSCC) ve Bowen hastalığı","group": "Deri tümörleri","guidePage": 257,"conditions": ["cutaneous-squamous-cell-carcinoma","squamous-cell-carcinoma-in-situ"],"appearance": "cSCC: keratotik, büyüyen, hassas nodül/ ülser; M. Bowen: keskin sınırlı, eritemli, skuamlı plak (in situ)","diagnosis": "Klinik ve dermoskopik bulgularla örneklemeyi planla. Kesin ayrım ve risk sınıflaması histolojiye dayanır.","alerts": "Organ nakli/ immünsüpresyon, hızlı büyüme, dudak/ kulak/ genital yerleşim, nüks, LAP, perinöral belirtiler","approach": "İnvaziv cSCC ve in situ Bowen lezyonunu histolojiyle ayır. İnvazyon, lokalizasyon ve nüks riski tedavi planını değiştirir.","sources": [["AWMF 032-022OL · Register","https://register.awmf.org/de/leitlinien/detail/032-022OL"]]},
    "2.19": {"germanName": "Larva migrans cutanea (Hautmaulwurf)","turkishName": "Kutanöz larva migrans","group": "Parazitler / seyahat dermatolojisi","guidePage": 260,"conditions": [],"appearance": "Tropik plaj/ kum teması sonrası ayak, kalça veya ellerde günde birkaç mm–cm ilerleyen, kaşıntılı, kıvrımlı (serpijinöz) kırmızı iz","diagnosis": "Klinik (seyahat anamnezi); hookworm folikülit varyantı","alerts": "Süperenfeksiyon, Löffler sendromu (nadir), larva currens (strongiloidoz – hızlı ilerleyen perianal iz)","approach": "Seyahat ve maruziyet öyküsüyle kıvrımlı izi değerlendir. Hız ve dağılım uyumsuzsa larva currens ve diğer ayırıcıları düşün.","sources": [["PubMed · 42886368","https://pubmed.ncbi.nlm.nih.gov/42886368/"]]},
    "2.20": {"germanName": "Lentigo maligna (Melanoma in situ) und Lentigo-maligna-Melanom","turkishName": "Lentigo maligna (in situ melanom) ve lentigo maligna melanomu","group": "Deri tümörleri (malign)","guidePage": 263,"conditions": ["lentigo-maligna","lentigo-maligna-melanoma"],"appearance": "Yaşlıda yüzde (yanak, burun) yavaş büyüyen, düzensiz sınırlı, renk tonları değişken kahverengi-siyah makül","diagnosis": "Folikül çevresindeki asimetrik pigment, gri noktalar ve açılı çizgileri değerlendir. Örnekleme planını lezyon dağılımı ve invazyon şüphesine göre yap.","alerts": "Papül/ nodül gelişimi (invazyon: LMM), hızlı renk değişimi","approach": "Yüzde değişen pigmente lezyonda dermoskopik olarak şüpheli alanı belgele ve örnekleme planla. Histolojik invazyon tedaviyi değiştirir.","sources": []},
    "2.21": {"germanName": "Lichen planus","turkishName": "Liken planus","group": "Otoimmün ve inflamatuvar hastalıklar (özel)","guidePage": 266,"conditions": ["lichen-planus"],"appearance": "Kaşıntılı, mor-poligonal, düz yüzeyli papüller (Wickham çizgileri), fleksör el bileği; ağızda retiküler beyaz ağ/ erozyon","diagnosis": "Klinik + gerekirse biyopsi; HCV serolojisi (bölgesel), ilaç anamnezi (likenoid ilaç reaksiyonu)","alerts": "Erozif oral/ genital LP (SCC riski), ülser değişikliği, liken planopilaris (skar)","approach": "Deri, mukoza, saçlı deri ve tırnak tutulumunu ayrı değerlendir. Erozif veya skarla giden tutulum takip planını değiştirir.","sources": []},
    "2.22": {"germanName": "Lichen sclerosus","turkishName": "Liken skleroz","group": "Otoimmün ve inflamatuvar hastalıklar (özel)","guidePage": 269,"conditions": [],"appearance": "Anogenital porselen beyazı, atrofik plaklar, purpura, fissür; mimari kayıp (labia rezorpsiyonu, fimozis)","diagnosis": "Klinik; atipik/ dirençli/ hiperkeratotik/ ülserli alanda biyopsi (dVIN/ SCC)","alerts": "Kalıcı ülser, nodül, hiperkeratoz, tedaviye yanıtsızlık veya idrar akımında sorun.","approach": "Yerleşim, skar ve fonksiyon etkisini belgele. Persistan ülser, nodül veya hiperkeratozda histoloji ihtiyacını değerlendir.","sources": [["AWMF 013-105 · Register","https://register.awmf.org/de/leitlinien/detail/013-105"]]},
    "2.23": {"germanName": "Malignes Melanom und suspekte Pigmentläsion","turkishName": "Malign melanom ve şüpheli pigmentli lezyon","group": "Deri tümörleri","guidePage": 272,"conditions": ["cutaneous-melanoma"],"appearance": "Renk ve yapı asimetrisi, değişim veya diğer benlerden farklı görünüm. Yeni ve büyüyen nodüllerde pigment bulunmayabilir.","diagnosis": "Öykü, muayene ve dermoskopi. Şüpheli lezyonda uygun biyopsi veya eksizyon yöntemini güncel kılavuza göre planla.","alerts": "Hızla değişen/ kanayan pigmentli lezyon, yeni nodül, subungual longitudinal melanonişi (Hutchinson), çok sayıda atipik nevüs","approach": "Şüpheli lezyonda doku tanısı ve histolojiye dayalı evreleme önceliklidir. Onkolojik tedavi ve izlem kararını güncel protokolle eşleştir.","sources": [["AWMF 032-024OL · Register","https://register.awmf.org/de/leitlinien/detail/032-024OL"]]},
    "2.24": {"germanName": "Merkelzellkarzinom","turkishName": "Merkel hücreli karsinom","group": "Deri tümörleri (malign)","guidePage": 275,"conditions": ["merkel-cell-carcinoma"],"appearance": "Yaşlıda güneş gören bölgede hızlı büyüyen, ağrısız, kırmızı-mor, parlak nodül (AEIOU: Asymptomatic, Expanding rapidly, Immunosuppression, Older than 50, UV-exposed)","diagnosis": "Eksizyonel biyopsi (CK20 nokta şeklinde, nöroendokrin belirteçler, MCPyV); evreleme (sonografi, SLNB, PET-BT/ BT)","alerts": "Hızla büyüyen nodül, bölgesel lenfadenopati ve immünsüpresyon.","approach": "Hızla büyüyen şüpheli nodülde doku tanısı ve uygun uzman merkez değerlendirmesi gerekir. Evreleme ve tedavi tümör kurulunda planlanır.","sources": [["AWMF 032-023 · Register","https://register.awmf.org/de/leitlinien/detail/032-023"]]},
    "2.25": {"germanName": "Mycosis fungoides (kutanes T-Zell-Lymphom)","turkishName": "Mikozis fungoides (kutanöz T hücreli lenfoma)","group": "Deri lenfomaları","guidePage": 278,"conditions": ["mycosis-fungoides"],"appearance": "Güneş görmeyen bölgelerde (kalça, uyluk, gövde – “mayo bölgesi”) değişken boyutta, ince skuamlı, kırışık yamalar; plak ve tümör evreleri; hipopigmente varyant (koyu ten, genç)","diagnosis": "Tekrarlanan biyopsiler (tedaviye ara verdikten sonra), immünohistokimya, TCR klonalite; kan (Sézary hücreleri, akım sitometri); evreleme","alerts": "Eritrodermi + LAP (Sézary sendromu), hızlı büyüyen tümörler, ülserasyon, B semptomları","approach": "Dirençli yama veya plaklarda seri klinik-patolojik değerlendirme gerekebilir. Evreye göre deri yönelimli ve sistemik yaklaşımı ayır.","sources": [["AWMF 032-027 · Register","https://register.awmf.org/de/leitlinien/detail/032-027"]]},
    "2.26": {"germanName": "Nekrotisierende Fasziitis (nekrotisierende Weichgewebeinfektion)","turkishName": "Nekrotizan fasiit (nekrotizan yumuşak doku enfeksiyonu)","group": "Acil / bakteriyel enfeksiyonlar","guidePage": 281,"conditions": [],"appearance": "Bulgulara oranla aşırı şiddetli ağrı, hızla yayılan eritem/ ödem, gri-mor renk değişimi, hemorajik bül, krepitasyon, anestezi; sepsis","diagnosis": "Klinik şüphe yeterli – görüntüleme cerrahiyi geciktirmemeli; LRINEC tek başına dışlamaz; cerrahi eksplorasyon tanı koyar","alerts": "Tüm belirtiler kırmızı bayraktır; özellikle diyabet, immünsüpresyon, IV ilaç kullanımı, varisella sonrası çocuk","approach": "Orantısız ağrı veya hızlı progresyonla nekrotizan enfeksiyon şüphesinde gecikmeden cerrahi acil değerlendirme gerekir.","sources": [["IDSA · Skin and soft tissue infections","https://www.idsociety.org/practice-guideline/skin-and-soft-tissue-infections/"],["PubMed · 30920745","https://pubmed.ncbi.nlm.nih.gov/30920745/"]]},
    "2.27": {"germanName": "Pediculosis capitis (Kopflausbefall)","turkishName": "Baş biti (pedikülozis kapitis)","group": "Parazitler","guidePage": 284,"conditions": [],"appearance": "Saçlı deride kaşıntı, ense/kulak arkasında ekskoriasyon; canlı bit ve saça yapışık sirkeler","diagnosis": "Nemli saçta bit tarağı ile canlı bit tespiti (yalnız sirke yetmez)","alerts": "Tekrarlayan/ dirençli olgular, yaygın süperenfeksiyon, kirpik tutulumu (Phthiriasis ayırımı)","approach": "Canlı bit varlığını değerlendir. Ürün, uygulama ve tekrar zamanını kullanım talimatına göre seç.","sources": []},
    "2.28": {"germanName": "Pemphigus vulgaris","turkishName": "Pemfigus vulgaris","group": "Otoimmün ve inflamatuvar hastalıklar (özel)","guidePage": 287,"conditions": ["pemphigus-vulgaris"],"appearance": "İnatçı ağrılı ağız erozyonları (sıklıkla ilk bulgu), gevşek büller ve erozyonlar, Nikolsky +","diagnosis": "Biyopsi (akantoliz) + DIF (intersellüler IgG/C3); Dsg1/Dsg3 ELISA","alerts": "Yaygın erozyon, beslenme bozukluğu, sepsis, göz/ larinks tutulumu","approach": "Mukoza ve deri yaygınlığı ile enfeksiyon ve beslenme riskini değerlendir. Sistemik tedaviyi uzman merkezle planla.","sources": [["AWMF 013-071 · Register","https://register.awmf.org/de/leitlinien/detail/013-071"]]},
    "2.29": {"germanName": "Phototoxische und photoallergische Reaktion (inkl. Phytophotodermatitis)","turkishName": "Fototoksik ve fotoalerjik reaksiyon (fitofotodermatit dahil)","group": "Fotodermatozlar","guidePage": 290,"conditions": [],"appearance": "Fototoksik: güneş gören alanlarda yoğun “güneş yanığı” + bül, sonra hiperpigmentasyon; fitofotodermatit: çizgisel/ damla şeklinde lezyon. Fotoalerjik: ekzematöz, kaşıntılı, gölgede kalan alanlara yayılabilir","diagnosis": "Anamnez (ilaç: Doxycyclin, NSAİİ, HCT, Amiodaron, Voriconazol; bitkiler: Bärenklau/ Riesen-Bärenklau, limon/ lime, incir; topikal: Ketoprofen, UV filtreleri – Octocrylen, Benzophenon); fotoyama testi","alerts": "Geniş bül, ateş, mukoza tutulumu (SJS/ fototoksik TEN ayırımı), göz tutulumu; Voriconazol/ HCT ile uzun süreli kullanımda deri kanseri riski","approach": "Işık, ilaç ve bitki temasının zaman ilişkisini değerlendir. Fototoksik ve fotoalerjik paternlerde korunma ve tetikleyici yönetimi farklı olabilir.","sources": []},
    "2.30": {"germanName": "Pityriasis rosea","turkishName": "Pityriasis rosea (gül hastalığı)","group": "Enfeksiyonlar (özel)","guidePage": 293,"conditions": [],"appearance": "Önce “madalyon” (herald patch), 1–2 hafta sonra gövdede deri çizgilerine paralel (“Tannenbaum”) oval, kenarı skuamlı plaklar","diagnosis": "Klinik; sekonder sifiliz serolojisi (özellikle avuç-taban tutulumu/ risk) ve ilaç anamnezi","alerts": "Atipik, uzayan veya mukoza ve avuç-tabanı tutan tabloda ayırıcı tanı. Gebelikte döküntüyü ilgili uzmanla değerlendir.","approach": "Özellikle atipik dağılımda ayırıcı tanıyı gözden geçir. Kaşıntı ve yaşam kalitesine göre destekleyici bakım planla.","sources": [["PubMed · 31684696","https://pubmed.ncbi.nlm.nih.gov/31684696/"]]},
    "2.31": {"germanName": "Pityriasis rubra pilaris","turkishName": "Pitiriyazis rubra pilaris","group": "Papüloskuamöz hastalıklar","guidePage": 296,"conditions": [],"appearance": "Turuncu-kırmızı folliküler papüller birleşerek plaklar, aralarında sağlam deri adaları (“nappes claires”), palmoplantar turuncu keratoderma; eritrodermiye gidebilir","diagnosis": "Klinik + biyopsi (psoriasis ayırımı; tekrar gerekebilir); eritrodermide sistemik değerlendirme","alerts": "Eritrodermi (ısı/ sıvı kaybı, enfeksiyon), HIV ilişkili tip VI","approach": "Yaygınlık ve eritrodermi riskini değerlendir. Sistemik tedaviyi uzman izlemiyle seç.","sources": [["PubMed · 43043176","https://pubmed.ncbi.nlm.nih.gov/43043176/"]]},
    "2.32": {"germanName": "Polymorphe Lichtdermatose","turkishName": "Polimorf ışık erüpsiyonu (güneş alerjisi)","group": "Fotodermatozlar","guidePage": 299,"conditions": [],"appearance": "Güneşe maruziyetten saatler–günler sonra açık alanlarda (dekolte, kollar) kaşıntılı papül, vezikül, plaklar; yüz çoğunlukla korunur","diagnosis": "Klinik + öykü; ayırıcı: SCLE (ANA, anti-Ro), fototoksik/ fotoalerjik reaksiyon, solar ürtiker, porfiri","alerts": "Yüzde skar/ atrofi, eklem ağrısı, sistemik belirti (LE), su ile yanma/ bül (porfiri)","approach": "Işık maruziyetinin dağılımını ve tekrarını sorgula. Fotoproteksiyon planla ve atipik bulguda lupus veya diğer fotodermatozları değerlendir.","sources": [["AWMF 013-029 · Register","https://register.awmf.org/de/leitlinien/detail/013-029"]]},
    "2.33": {"germanName": "Prurigo nodularis / chronische noduläre Prurigo","turkishName": "Prurigo nodülaris (kronik nodüler prurigo)","group": "Kronik inflamatuvar hastalıklar (özel)","guidePage": 302,"conditions": [],"appearance": "Çok sayıda, simetrik, kaşıntılı, sert, hiperkeratotik/ ekskoriye nodül; sırt ortası korunur (“kelebek işareti”)","diagnosis": "Klinik; altta yatan neden araştırması (kronik pruritus laboratuvarı, atopi, böbrek/ KC, HIV, malignite)","alerts": "Ağır uyku bozukluğu, depresyon, sistemik altta yatan hastalık (lenfoma, KC/ böbrek)","approach": "Kaşıntı döngüsü ve sistemik nedenleri araştır. Tedaviyi şiddet, yaşam kalitesi ve eşlik eden hastalıklarla planla.","sources": [["AWMF 013-048 · Register","https://register.awmf.org/de/leitlinien/detail/013-048"]]},
    "2.34": {"germanName": "Staphylococcal Scalded Skin Syndrome (SSSS, staphylogenes Lyell-Syndrom)","turkishName": "Stafilokokal haşlanmış deri sendromu (SSSS)","group": "Acil / bakteriyel enfeksiyonlar","guidePage": 305,"conditions": [],"appearance": "Küçük çocukta ateş, huzursuzluk, ağrılı yaygın eritem; kıvrımlarda ve periorifisyel başlayan yüzeysel soyulma; Nikolsky pozitif; mukoza TUTULMAZ","diagnosis": "Klinik; kültür (burun, konjunktiva, göbek, odak – bül içeriği steril); gerekirse frozen section (subkorneal ayrılma; TEN’den ayırım)","alerts": "Yenidoğan/ süt çocuğu, dehidratasyon, sepsis, erişkinde böbrek yetmezliği/ immünsüpresyon","approach": "Çocukta hassas, yaygın eritem ve deri soyulması acil pediatrik değerlendirme gerektirir. Sıvı kaybı ve enfeksiyon önceliklidir.","sources": []},
    "2.35": {"germanName": "Syphilis","turkishName": "Sifiliz (frengi)","group": "Enfeksiyonlar (özel)","guidePage": 308,"conditions": [],"appearance": "Primer: ağrısız, sert tabanlı ülser (şankr) + LAP; sekonder: avuç-taban dahil makülopapüler ekzantem, kondiloma lata, alopesi “güve yeniği”","diagnosis": "Klinik şüphe ve evreye uygun treponemal ve nontreponemal testleri birlikte değerlendir. Gerektiğinde enfeksiyon uzmanı ile sonuçları yorumla.","alerts": "Nörolojik/ oküler/ otik semptomlar (nörosifiliz), gebelik, HIV","approach": "Evrelendirme, nörolojik-oküler-otik belirti, gebelik ve HIV durumunu değerlendir. Bunlar tedavi şemasını ve takip planını değiştirir.","sources": [["AWMF 059-002 · Register","https://register.awmf.org/de/leitlinien/detail/059-002"]]},
    "2.36": {"germanName": "Tinea capitis","turkishName": "Tinea kapitis (saçlı deri mantarı)","group": "Enfeksiyonlar (özel)","guidePage": 312,"conditions": ["tinea-capitis"],"appearance": "Çocukta skuamlı alopesik yama(lar), kırık kıllar, siyah noktalar; kerion (inflamatuvar, püstüler, ağrılı kitle)","diagnosis": "Mikroskopi + kültür (± PCR) tedaviden önce; Wood (Microsporum: yeşil floresans)","alerts": "Kerion (yanlışlıkla insizyon yapılmamalı), skar riski, salgın (kreş/okul), id reaksiyonu","approach": "Saçlı deri mantarında etken ve klinik yaygınlığı değerlendir. Sistemik ajan seçiminde çocuk yaşı ve preparat bilgisi önemlidir.","sources": [["AWMF 013-033 · Register","https://register.awmf.org/de/leitlinien/detail/013-033"]]},
    "2.37": {"germanName": "Ulcus cruris venosum","turkishName": "Venöz bacak ülseri","group": "Yara ve bakım","guidePage": 315,"conditions": [],"appearance": "Medial malleol çevresinde sığ, düzensiz ülser; çevrede staz dermatiti, hiperpigmentasyon, lipodermatoskleroz, atrofi blanş","diagnosis": "Arteriyel ve venöz dolaşımı değerlendir. Kompresyon kararında damar değerlendirmesini ve yerel yara bakım protokolünü kullan.","alerts": "İskemi bulguları, hızla yayılan enfeksiyon, sistemik semptomlar veya atipik, iyileşmeyen ülser.","approach": "Uygun kompresyon için arteriyel ve venöz dolaşımı değerlendir. Genel yara bakımıyla birlikte atipik ülser ve enfeksiyon olasılığına dikkat et.","sources": [["AWMF 037-009 · Register","https://register.awmf.org/de/leitlinien/detail/037-009"]]},
    "2.38": {"germanName": "Windeldermatitis","turkishName": "Bez dermatiti (pişik)","group": "Yara ve bakım","guidePage": 319,"conditions": [],"appearance": "Bez temas alanında eritem; kıvrımlar korunur (irritan); kıvrım tutulumu + satellit püstül (Candida)","diagnosis": "Klinik; Candida şüphesinde KOH; dirençli/ atipikte psoriasis, SD, LCH, akrodermatit (çinko) ayırımı","alerts": "Ülser, papül/ nodül, ateş, gelişme geriliği, purpura (LCH), dirençli tablo","approach": "Temas ve nemi azaltıp bariyeri koru. Kıvrım tutulumu ve satellit lezyonlar varsa Candida olasılığını değerlendir.","sources": []},
    "2.39": {"germanName": "Zirkumskripte Sklerodermie (Morphea)","turkishName": "Morfea (lokalize skleroderma)","group": "Kollajenozlar / sklerozan","guidePage": 322,"conditions": [],"appearance": "Aktif kenarda lila halka (“lilac ring”), ortası sertleşmiş fildişi beyazı plak; lineer form (en coup de sabre) yüz/ ekstremite","diagnosis": "Klinik (aktivite ve hasar ayrımı), gerekirse biyopsi; sonografi; Raynaud/ kapillaroskopi (SSc ayırımı); linear formda nöroloji/ göz/ ortopedi","alerts": "Lineer form (eklem kontraktürü, büyüme geriliği, yüz atrofisi, nörolojik/ göz tutulumu), Raynaud + organ bulgusu (SSc)","approach": "Aktiviteyi, derinliği ve yerleşimi belgele. Lineer, yüz veya eklem çevresi tutulumunda uzmanlıklar arası değerlendirme gerekebilir.","sources": [["AWMF 013-066 · Register","https://register.awmf.org/de/leitlinien/detail/013-066"]]},
  },
  handouts: {
    "isotretinoin": {"page": "2–3","title": "İzotretinoin","germanName": "Isotretinoin","about": "Bazı ağır veya iz bırakma riski yüksek akne türlerinde doktorunuz bu kapsülü önerebilir.","treatment": "Uygulama, kan tahlilleri ve takip planını hekiminizle görüşün. Gebelik açısından resmî korunma programı uygulanır.","daily": "Kapsüllerinizi başkalarıyla paylaşmayın. Kuruluk veya başka yan etki olursa size verilen iletişim yolunu kullanın.","contact": "Gebelik olasılığı, ciddi ruh hâli değişikliği veya şiddetli baş ağrısıyla birlikte görme bozukluğunda hemen tıbbi yardım alın."},
    "1.6": {"page": "6","title": "Atopik dermatit","germanName": "Atopische Dermatitis","about": "Ciltte kuruluk, kaşıntı ve zaman zaman alevlenen egzama alanları görülebilir.","treatment": "Doktorunuz temel bakım ve atak tedavisi için ayrı bir plan verebilir. Hangi ürünün hangi bölgeye uygulanacağını sorun.","daily": "Cildinizi nazikçe temizleyin ve önerilen nemlendiriciyle düzenli bakım yapın.","contact": "Ateş, ağrılı su kabarcıkları veya hızla yayılan yaralar varsa aynı gün tıbbi yardım alın."},
    "sun-protection": {"page": "7","title": "Güneşten korunma","germanName": "Sonnenschutz","about": "Güneşin UV ışınları güneş yanığına ve zamanla kalıcı cilt hasarına neden olabilir.","treatment": "Gölge, sık dokunmuş giysi, geniş kenarlı şapka ve güneş koruyucuyu birlikte kullanın.","daily": "Güneş koruyucuyu açıkta kalan cilde yeterli miktarda sürün. Yüzme, terleme ve havluyla kurulanma sonrası yenileyin.","contact": "Yeni veya değişen bir leke, kanama ya da iyileşmeyen bir yara fark ederseniz muayene olun."},
    "1.39": {"page": "8","title": "Sedef hastalığı","germanName": "Psoriasis vulgaris","about": "Sedef, kızarık ve pullu plaklar yapabilen kronik bir hastalıktır. Bulaşıcı değildir.","treatment": "Tedavi cildin, tırnakların ve varsa eklemlerin ne kadar etkilendiğine göre seçilir.","daily": "Nemlendiriciyi ve reçetenizdeki ürünleri size anlatıldığı şekilde uygulayın. Eklemlerdeki yeni belirtileri kaydedin.","contact": "Eklem şişliği, sabah tutukluğu veya sedefin hızla yayılması durumunda muayenehanenize haber verin."},
    "1.40": {"page": "9","title": "Rozasea (gül hastalığı)","germanName": "Rosazea","about": "Rozaseada yüzün orta bölgesinde kalıcı kızarıklık, sıcak basması veya iltihaplı küçük kabarıklıklar olabilir.","treatment": "Tedavi baskın belirtiye göre seçilir. Göz yakınmalarınızı da hekiminize söyleyin.","daily": "Nazik temizleyici ve tolere ettiğiniz güneş koruyucuyu kullanın. Kızarıklığı artıran kişisel tetikleyicileri gözlemleyin.","contact": "Göz ağrısı, ışığa bakamama veya görme azalması olursa gecikmeden tıbbi yardım alın."},
    "1.41": {"page": "10","title": "Seboreik dermatit","germanName": "Seborrhoische Dermatitis","about": "Saçlı deri, kaş ve burun kenarında kızarıklık ve yağlı pullanma görülebilir.","treatment": "Tedavi cildin bölgesine göre seçilir. Şampuan veya kremi uygulama planına göre kullanın.","daily": "Pulları kazımayın. Yakınmaların tekrar etmesi hâlinde bakım planınızı muayenehanenizle gözden geçirin.","contact": "Yaygın veya ağrılı kızarıklık, akıntı ya da tedaviye rağmen kötüleşme varsa başvurun."},
    "1.48": {"page": "11","title": "Ayak ve deri mantarı","germanName": "Tinea pedis und Tinea corporis","about": "Deri mantarı kaşıntı, pullanma veya parmak aralarında çatlama yapabilir.","treatment": "Doktorunuz gerekirse örnek alır. Mantar ilacını tarif edilen bölgeye ve verilen süre boyunca uygulayın.","daily": "Parmak aralarını iyi kurulayın. Havlu ve ayakkabıları paylaşmayın.","contact": "Kızarıklık hızla yayılırsa, ağrı veya ateş gelişirse ya da şeker hastalığınız varsa yardım alın."},
    "1.51": {"page": "12","title": "Siğil","germanName": "Warzen","about": "Siğiller virüs kaynaklı pürtüklü oluşumlardır. Ayak tabanındaki siğil basınca ağrıyabilir.","treatment": "İzlem veya tedavi seçimi yaşa, bölgeye ve yakınmalara göre yapılır.","daily": "Siğili koparmayın. Evde bir ürün kullanacaksanız yalnızca hekiminizin gösterdiği lezyona ve önerilen şekilde uygulayın.","contact": "Oluşum kanar, hızla değişir veya tanısından emin olamazsanız muayene olun."},
    "1.17": {"page": "13","title": "Zona","germanName": "Herpes zoster","about": "Zona genellikle vücudun bir tarafında ağrı ve grup hâlinde su kabarcıkları yapar.","treatment": "Tedavi için erken başvurun. Ağrı ve döküntü başladığı zamanı hekiminize söyleyin.","daily": "Kabarcıkları kaşımayın, kapalı tutun ve el hijyenine dikkat edin. Riskli kişilerle temas konusunu muayenehanenize sorun.","contact": "Göz veya kulak çevresinde döküntü, yüz kaslarında güçsüzlük, görme değişikliği ya da yaygın döküntü varsa gecikmeden yardım alın."},
    "1.49": {"page": "14","title": "Kurdeşen (ürtiker)","germanName": "Urtikaria","about": "Kurdeşen, gelip giden kaşıntılı kabarıklıklar yapabilir. Bazı kişilerde derinin derin katmanlarında da şişlik olur.","treatment": "Tedavi yakınmaların süresine, tekrarlamasına ve eşlik eden bulgulara göre seçilir.","daily": "Kabarıklıkların fotoğrafını çekmek ve ne kadar sürdüğünü not etmek muayeneyi kolaylaştırabilir.","contact": "Nefes darlığı, dil veya boğaz şişliği ya da bayılma hissinde acil yardım çağırın."},
    "1.7": {"page": "15","title": "Kronik el egzaması","germanName": "Chronisches Handekzem","about": "Ellerde kızarıklık, çatlak, kaşıntı veya minik su kabarcıkları görülür.","treatment": "Hekiminiz cilt bakımı, atak tedavisi ve gerekirse alerji değerlendirmesi planlar.","daily": "Ellerinizi nazikçe yıkayın ve düzenli nemlendirin. Islak iş ve eldiven kullanımını muayenede konuşun.","contact": "Çatlaklar derinleşirse, ağrı ve kızarıklık artarsa veya ellerinizi kullanmak zorlaşırsa başvurun."},
    "1.42": {"page": "16","title": "Seboreik keratoz","germanName": "Seborrhoische Keratose","about": "Bu oluşum çoğu zaman cilde yapışık gibi görünen, kabarık, iyi huylu bir deri değişikliğidir.","treatment": "Tipik oluşumlarda tedavi gereksinimi yakınmaya göre belirlenir. Tanıyı hekiminiz değerlendirir.","daily": "Oluşumu kazımayın veya evde yakmaya çalışmayın.","contact": "Yeni renk değişikliği, hızlı büyüme, kanama veya yara olursa kontrol ettirin."},
    "1.27": {"page": "17","title": "Deri kanseri taraması ve benler","germanName": "Hautkrebs-Screening und Muttermale","about": "Cilt muayenesi ve dermoskopi, benlerin ve diğer deri lezyonlarının değerlendirilmesine yardımcı olur.","treatment": "Hekiminiz görünüm ve kişisel risklere göre izlem veya doku incelemesi planlayabilir.","daily": "Cildinizi düzenli kontrol edin ve fark ettiğiniz değişikliğin ne zaman başladığını not edin.","contact": "Yeni veya büyüyen bir leke, değişen renk ve şekil, kanama ya da iyileşmeyen yara varsa tarama randevusunu beklemeden başvurun."},
    "1.3": {"page": "18","title": "Kalıtsal saç dökülmesi","germanName": "Androgenetische Alopezie","about": "Saçlar tepe veya şakaklarda ya da orta ayrım çizgisi boyunca zamanla seyrekleşebilir.","treatment": "Tedavi seçenekleri yaşa, saç dökülmesi tipine ve kişisel durumunuza göre belirlenir.","daily": "Sonucu değerlendirmek zaman alabilir. İlk görünümü fotoğrafla kaydetmek değişimi izlemeye yardımcı olur.","contact": "Dökülme aniden başlarsa, yama yaparsa ya da saçlı deride kızarıklık, ağrı veya yara varsa başvurun."},
    "1.4": {"page": "19","title": "Alopesi areata (saçkıran)","germanName": "Alopecia areata","about": "Saçta veya sakalda yuvarlak, düzgün yüzeyli dökülme alanları oluşabilir. Bulaşıcı değildir.","treatment": "Hekiminiz dökülmenin yaygınlığına ve hızına göre izlem veya tedavi önerir.","daily": "Yeni alanları ve değişimleri not edin. Görünüm ruh hâlinizi etkiliyorsa bunu hekiminizle paylaşın.","contact": "Alanlar hızla yayılırsa veya kaş ve kirpik tutulumu fark ederseniz muayene olun."},
    "1.43": {"page": "20","title": "Uyuz","germanName": "Skabies","about": "Uyuzda özellikle geceleri artan kaşıntı ve küçük kabarıklıklar görülebilir. Yakın cilt temasıyla bulaşabilir.","treatment": "İlacı size verilen plana göre kullanın. Yakın temaslıların aynı zamanda değerlendirilmesi önemlidir.","daily": "Çamaşır ve giysiler için size verilen talimatları uygulayın. Tedavi sonrası kaşıntı bir süre devam edebilir.","contact": "Yeni tünel veya döküntüler oluşursa, evde yeni vaka fark ederseniz ya da ciltte enfeksiyon belirtileri çıkarsa başvurun."},
    "1.18": {"page": "21","title": "Aşırı terleme (hiperhidroz)","germanName": "Hyperhidrosis","about": "Aşırı terleme koltuk altı, el veya ayaklarda günlük yaşamı zorlaştırabilir.","treatment": "Doktorunuz terlemenin dağılımını ve altta yatan bir neden olup olmadığını değerlendirir.","daily": "Terlemenin ne zaman başladığını, hangi bölgeleri tuttuğunu ve gece olup olmadığını not edin.","contact": "Yeni gece terlemesi, açıklanamayan kilo kaybı veya ateş varsa muayene olun."},
    "1.23": {"page": "22","title": "Kontakt egzama","germanName": "Kontaktekzem","about": "Bir maddeyle temas sonrası kızarıklık, kaşıntı, çatlak veya su kabarcıkları görülebilir.","treatment": "Hekiminiz temas öykünüzü değerlendirir. Gerekirse alerji için yama testi planlanır.","daily": "Şüpheli ürünlerin adlarını veya ambalajlarını muayeneye getirin. Önerilen koruma ve bakım planını uygulayın.","contact": "Egzama yayılıyorsa, ağrı ya da akıntı artıyorsa veya yüz ve göz çevresi etkileniyorsa başvurun."},
  },
};
